'use strict';
const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d');
const mp='https://transparencia.mprj.mp.br/web/guest/visualizar?noticiaId=96203';
const tj='https://www.tjrj.jus.br/home?_com_liferay_portal_search_web_portlet_SearchPortlet_assetEntryId=92111651&_com_liferay_portal_search_web_portlet_SearchPortlet_mvcPath=%2Fview_content.jsp&p_p_id=com_liferay_portal_search_web_portlet_SearchPortlet&p_p_lifecycle=0&p_p_state=maximized';
const dossiers=[
{tag:'ACUSAÇÃO · 2020',title:'Uma denúncia não é uma condenação',text:'O MPRJ informou que apresentou denúncia em 19/10/2020 contra Flávio Bolsonaro, Fabrício Queiroz e outros 15 investigados. A peça apontava supostos crimes ocorridos entre 2007 e 2018. São acusações do Ministério Público, não fatos estabelecidos por condenação.',url:mp,label:'Comunicado do MPRJ — 04/11/2020'},
{tag:'CONTEXTO · 2020',title:'O gabinete no centro do caso',text:'O caso ficou conhecido como “rachadinhas”: suspeitas de apropriação de parte dos salários de servidores do gabinete. Flávio nega irregularidades. A denúncia citou peculato, lavagem de dinheiro, organização criminosa e apropriação indébita; o processo teve desfecho posterior mostrado na terceira fase.',url:mp,label:'Denúncia anunciada pelo MPRJ'},
{tag:'DECISÃO JUDICIAL · 2022',title:'As provas foram anuladas. A denúncia, rejeitada.',text:'Em 16/05/2022, o TJRJ informou a rejeição da denúncia depois da anulação de provas pelo STJ e STF. O próprio MP pediu a extinção da denúncia. A nota do tribunal registra que a rejeição por falta de justa causa não impede o retorno das investigações. Este documento descreve aquela decisão, sem afirmar que houve reabertura posterior.',url:tj,label:'Nota oficial do TJRJ — 16/05/2022'}];
$('cards').innerHTML=dossiers.map(d=>`<article><span class="tag">${d.tag}</span><h3>${d.title}</h3><p>${d.text}</p><a href="${d.url}" target="_blank" rel="noopener noreferrer">${d.label}</a></article>`).join('');
let mode='ready',level=0,lives=3,docs=[],platforms=[],hazards=[],player,camera=0,time=0,last=0,invincible=0;const keys=new Set();const W=2560;const names=['O gabinete dos atalhos','O carimbo nunca dorme','O arquivo completo'];
const bg=new Image();bg.src='archive.webp';
function setup(){player={x:60,y:350,w:28,h:42,vx:0,vy:0,ground:false};camera=0;invincible=0;platforms=[{x:0,y:430,w:480,h:50},{x:570,y:430,w:480,h:50},{x:1140,y:430,w:550,h:50},{x:1800,y:430,w:760,h:50},{x:210,y:330,w:130,h:18},{x:430,y:260,w:150,h:18},{x:760,y:320,w:170,h:18},{x:1020,y:245,w:170,h:18},{x:1340,y:330,w:160,h:18},{x:1600,y:265,w:190,h:18},{x:1900,y:330,w:180,h:18},{x:2140,y:255,w:160,h:18}];docs=[{x:470,y:214,taken:false},{x:1080,y:199,taken:false},{x:2200,y:209,taken:false}];hazards=[{base:650,x:650,y:396,w:36,h:34,range:110},{base:1270,x:1270,y:396,w:36,h:34,range:110},{base:1950,x:1950,y:396,w:36,h:34,range:100}];$('levelno').textContent=String(level+1).padStart(2,'0');$('levelname').textContent=names[level];updateHud();}
function updateHud(){$('count').textContent=`0${docs.filter(d=>d.taken).length} / 03`;$('lives').textContent=String(lives).padStart(2,'0');}
function overlay(title,text,button,action){mode='overlay';keys.clear();$('overlay').hidden=false;$('overlay').innerHTML=`<span class="stamp">${level===2?'ARQUIVO COMPLETO':'DOCUMENTO DESBLOQUEADO'}</span><h1>${title}</h1><p>${text}</p><button id="advance">${button}</button>`;$('advance').onclick=action;}
function start(){level=0;lives=3;setup();mode='playing';$('overlay').hidden=true;$('hint').textContent='Colete os três documentos e alcance o terminal verde.';}
$('start').onclick=start;
function togglePause(){if(mode==='playing'){mode='paused';keys.clear();$('hint').textContent='Pausado. Toque em Ⅱ ou pressione P para continuar.';}else if(mode==='paused'){mode='playing';$('hint').textContent='Colete os três documentos e alcance o terminal verde.';}}
$('pause').onclick=togglePause;let beforeDialog;
$('sources').onclick=()=>{beforeDialog=mode;if(mode==='playing')mode='paused';keys.clear();$('dossier').showModal();};$('close').onclick=()=>$('dossier').close();$('dossier').addEventListener('close',()=>{if(beforeDialog==='playing')mode='playing';});
window.addEventListener('keydown',e=>{if($('dossier').open)return;if(['ArrowLeft','ArrowRight','ArrowUp','Space'].includes(e.code))e.preventDefault();if(e.code==='KeyP'&&!e.repeat)togglePause();keys.add(e.code);if(['Space','ArrowUp','KeyW'].includes(e.code)&&!e.repeat)jump();});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();if(mode==='playing')togglePause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='playing')togglePause();});
for(const b of document.querySelectorAll('[data-key]')){b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key);if(b.dataset.key==='Space')jump();});for(const evt of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(evt,()=>keys.delete(b.dataset.key));}
function jump(){if(mode==='playing'&&player.ground){player.vy=-630;player.ground=false;}}
function overlaps(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;}
function die(){lives--;updateHud();if(lives<=0){overlay('A burocracia venceu.<br>Por enquanto.','O arquivo continua aberto. Tente de novo.','RECOMEÇAR',start);return;}player.x=Math.max(60,camera+45);player.y=60;player.vy=0;invincible=2;}
function step(dt){time+=dt;invincible=Math.max(0,invincible-dt);player.vx=((keys.has('ArrowRight')||keys.has('KeyD')?1:0)-(keys.has('ArrowLeft')||keys.has('KeyA')?1:0))*270;player.x=Math.max(0,Math.min(W-player.w,player.x+player.vx*dt));const old=player.y;player.vy+=1550*dt;player.y+=player.vy*dt;player.ground=false;for(const p of platforms){if(player.vy>=0&&old+player.h<=p.y+2&&player.y+player.h>=p.y&&player.x+player.w>p.x&&player.x<p.x+p.w){player.y=p.y-player.h;player.vy=0;player.ground=true;}}
for(const h of hazards){h.x=h.base+Math.sin(time*(1+level*.2)+h.base)*h.range;if(invincible===0&&overlaps(player,h)){die();break;}}
for(const d of docs)if(!d.taken&&overlaps(player,{x:d.x,y:d.y,w:28,h:36})){d.taken=true;updateHud();$('hint').textContent='Documento coletado. Falta ler o contexto no fim da fase.';}
if(player.y>560)die();camera=Math.max(0,Math.min(W-960,player.x-320));if(player.x>2440){if(docs.every(d=>d.taken)){const d=dossiers[level];overlay(d.title,d.text,level<2?'PRÓXIMA FASE':'JOGAR NOVAMENTE',()=>{if(level<2){level++;lives=3;setup();mode='playing';$('overlay').hidden=true;}else start();});}else $('hint').textContent='O arquivo tem lacunas: volte e colete os três documentos.';}}
function draw(){ctx.fillStyle='#102d37';ctx.fillRect(0,0,960,480);if(bg.complete&&bg.naturalWidth){ctx.globalAlpha=.7;ctx.drawImage(bg,-camera*.12,0,1200,480);ctx.globalAlpha=1;}ctx.fillStyle='#061d27';ctx.fillRect(0,430,960,50);ctx.save();ctx.translate(-camera,0);for(const p of platforms){ctx.fillStyle='#365c60';ctx.fillRect(p.x,p.y,p.w,p.h);ctx.fillStyle='#a4b991';ctx.fillRect(p.x,p.y,p.w,4);ctx.fillStyle='#203f48';for(let x=p.x+10;x<p.x+p.w;x+=30)ctx.fillRect(x,p.y+12,18,5);}
ctx.font='28px sans-serif';for(const d of docs)if(!d.taken){ctx.fillStyle='#f7cb5824';ctx.fillRect(d.x-7,d.y-7,42,50);ctx.fillStyle='#f5e9bf';ctx.fillRect(d.x,d.y,27,34);ctx.fillStyle='#547472';for(let i=0;i<3;i++)ctx.fillRect(d.x+5,d.y+8+i*6,17,2);}
for(const h of hazards){ctx.fillStyle='#a84343';ctx.fillRect(h.x,h.y,h.w,h.h);ctx.fillStyle='#ffd1ad';ctx.font='bold 11px monospace';ctx.fillText('SIG',h.x+7,h.y+22);}
ctx.fillStyle='#36c19b';ctx.fillRect(2460,330,54,100);ctx.fillStyle='#102b32';ctx.fillRect(2468,338,38,45);ctx.fillStyle='#9defbe';ctx.font='11px monospace';ctx.fillText('LER',2476,365);ctx.fillStyle='#e7e3cb';ctx.font='40px sans-serif';if(invincible===0||Math.floor(time*12)%2===0)ctx.fillText('🕵',player.x-7,player.y+38);ctx.restore();if(mode==='paused'){ctx.fillStyle='#061722b0';ctx.fillRect(0,0,960,480);ctx.fillStyle='#f7cb58';ctx.textAlign='center';ctx.font='bold 32px monospace';ctx.fillText('PAUSADO',480,240);ctx.textAlign='left';}}
function frame(ts){const dt=Math.min((ts-last)/1000||0,.025);last=ts;if(mode==='playing')step(dt);draw();requestAnimationFrame(frame);}setup();requestAnimationFrame(frame);
